{
  "propositions": [
    {
      "text": "DPC (Ireland) Final Decision IN-20-8-1 concerns Meta Platforms Ireland Limited and GDPR data transfers.",
      "exactQuote": "DPC (Ireland) Final Decision IN-20-8-1 — Meta Platforms Ireland Limited (GDPR data transfers)",
      "blockId": "c-law-002#block-0"
    },
    {
      "text": "The decision date is 12 May 2023.",
      "exactQuote": "Decision Date: 12 May 2023",
      "blockId": "c-law-002#block-3"
    },
    {
      "text": "The announcement date is 22 May 2023.",
      "exactQuote": "Announcement Date: 22 May 2023",
      "blockId": "c-law-002#block-3"
    },
    {
      "text": "The authority is the Data Protection Commission (Ireland), Lead Supervisory Authority.",
      "exactQuote": "Authority: Data Protection Commission (Ireland), Lead Supervisory Authority",
      "blockId": "c-law-002#block-3"
    },
    {
      "text": "The EDPB Binding Decision was on 13 April 2023 under Article 65 dispute resolution.",
      "exactQuote": "EDPB Binding Decision: 13 April 2023 (Article 65 dispute resolution)",
      "blockId": "c-law-002#block-3"
    },
    {
      "text": "The case reference is IN-20-8-1.",
      "exactQuote": "Case Reference: IN-20-8-1",
      "blockId": "c-law-002#block-3"
    },
    {
      "text": "Meta Ireland infringed Article 46(1) GDPR when it continued to transfer personal data from the EU/EEA to the USA after the CJEU's judgment in Data Protection Commissioner v Facebook Ireland Limited and Maximillian Schrems.",
      "exactQuote": "The decision records that Meta Ireland infringed Article 46(1) GDPR when it continued to transfer personal data from the EU/EEA to the USA following the delivery of the CJEU's judgment in Data Protection Commissioner v Facebook Ireland Limited and Maximillian Schrems.",
      "blockId": "c-law-002#block-5"
    },
    {
      "text": "Meta Ireland effected those transfers on the basis of the updated Standard Contractual Clauses ('SCCs') adopted by the European Commission in 2021.",
      "exactQuote": "While Meta Ireland effected those transfers on the basis of the updated Standard Contractual Clauses ('SCCs') that were adopted by the European Commission in 2021",
      "blockId": "c-law-002#block-6"
    },
    {
      "text": "Meta Ireland implemented additional supplementary measures.",
      "exactQuote": "in conjunction with additional supplementary measures that were implemented by Meta Ireland",
      "blockId": "c-law-002#block-6"
    },
    {
      "text": "The DPC found that these arrangements did not address the risks to the fundamental rights and freedoms of data subjects identified by the CJEU in its judgment.",
      "exactQuote": "the DPC found that these arrangements did not address the risks to the fundamental rights and freedoms of data subjects that were identified by the CJEU in its judgment.",
      "blockId": "c-law-002#block-6"
    },
    {
      "text": "US law does not provide a level of protection equivalent to that provided by EU law.",
      "exactQuote": "US law does not provide a level of protection that is equivalent to that provided by EU law.",
      "blockId": "c-law-002#block-8"
    },
    {
      "text": "Neither the 2010 SCCs nor the 2021 SCCs could compensate for the inadequate protection provided by US law.",
      "exactQuote": "Neither the 2010 SCCs, nor the 2021 SCCs, could compensate for the inadequate protection provided by US law.",
      "blockId": "c-law-002#block-9"
    },
    {
      "text": "The measures set out in Meta's record of safeguards do not compensate for the inadequate protection provided by US law.",
      "exactQuote": "The measures set out in Meta's record of safeguards...do not compensate for the inadequate protection provided by US law.",
      "blockId": "c-law-002#block-10"
    },
    {
      "text": "It is not open to Meta to rely on the derogations provided for in Article 49(1) of the GDPR when making the data transfers.",
      "exactQuote": "It is not open to Meta to rely on the derogations provided for in Article 49(1) of the GDPR when making the data transfers.",
      "blockId": "c-law-002#block-11"
    },
    {
      "text": "An administrative fine of €1.2 billion was imposed, the largest GDPR fine ever.",
      "exactQuote": "Administrative fine: €1.2 billion — the largest GDPR fine ever imposed.",
      "blockId": "c-law-002#block-13"
    },
    {
      "text": "Meta Ireland must suspend any future transfer of personal data to the US within five months from notification under Article 58(2)(j) GDPR.",
      "exactQuote": "Suspension order (Article 58(2)(j) GDPR): Meta Ireland must suspend any future transfer of personal data to the US within five months from notification.",
      "blockId": "c-law-002#block-13"
    },
    {
      "text": "Meta Ireland must bring processing into compliance with Chapter V GDPR by ceasing unlawful processing, including storage, in the US within six months from notification under Article 58(2)(d) GDPR.",
      "exactQuote": "Compliance order (Article 58(2)(d) GDPR): Meta Ireland must bring processing into compliance with Chapter V GDPR by ceasing unlawful processing, including storage, in the US within six months from notification.",
      "blockId": "c-law-002#block-13"
    },
    {
      "text": "The EDPB found that Meta IE's infringement is very serious because it concerns transfers that are systematic, repetitive and continuous.",
      "exactQuote": "The EDPB found that Meta IE's infringement is very serious since it concerns transfers that are systematic, repetitive and continuous.",
      "blockId": "c-law-002#block-15"
    },
    {
      "text": "Facebook has millions of users in Europe, so the volume of personal data transferred is massive.",
      "exactQuote": "Facebook has millions of users in Europe, so the volume of personal data transferred is massive.",
      "blockId": "c-law-002#block-15"
    },
    {
      "text": "The unprecedented fine is a strong signal to organisations that serious infringements have far-reaching consequences.",
      "exactQuote": "The unprecedented fine is a strong signal to organisations that serious infringements have far-reaching consequences.",
      "blockId": "c-law-002#block-15"
    },
    {
      "text": "The DPC initially proposed only a suspension order without a fine.",
      "exactQuote": "The DPC initially proposed only a suspension order without a fine.",
      "blockId": "c-law-002#block-17"
    },
    {
      "text": "Four of 47 Concerned Supervisory Authorities objected to the DPC's initial proposal.",
      "exactQuote": "Four of 47 Concerned Supervisory Authorities objected.",
      "blockId": "c-law-002#block-17"
    },
    {
      "text": "The EDPB determined that a fine should be imposed and that Meta must also address already-transferred data.",
      "exactQuote": "The EDPB determined that a fine should be imposed and that Meta must also address already-transferred data.",
      "blockId": "c-law-002#block-17"
    },
    {
      "text": "The DPC was bound to follow the EDPB's binding decision.",
      "exactQuote": "The DPC was bound to follow the EDPB's binding decision.",
      "blockId": "c-law-002#block-17"
    },
    {
      "text": "Meta announced it would appeal the decision and seek a stay with the courts to pause implementation deadlines.",
      "exactQuote": "Meta announced it would appeal the decision and seek a stay with the courts to pause implementation deadlines.",
      "blockId": "c-law-002#block-19"
    }
  ]
}
